write_result() {          # $1=NAME $2=VALUE
  if [ "$#" -ne 2 ] || [[ ! "$1" =~ ^[A-Z_][A-Z0-9_]*$ ]] || [[ "$1" == __Y2B_* ]]; then
    echo "write_result: expected 'write_result NAME VALUE' with NAME matching ^[A-Z_][A-Z0-9_]*\$ (step $Y2B_STEP_NAME)" >> "$LOG_FILE"
    return 1
  fi
  printf '%s=%s\n' "$1" "$(printf '%s' "$2" | base64 -w0)" >> "$RES_FILE"
  printf '%s="%s"\n' "$1" "$2" >> "$LOG_FILE"
}
export -f write_result; export RES_FILE LOG_FILE

y2b_step_1() {            # check-os-release
  # Query Linux distribution and version
  if [ -f /etc/os-release ]; then
    . /etc/os-release
    write_result OS_NAME "$NAME"
    write_result OS_VERSION "$VERSION_ID"
  else
    write_result OS_NAME "UNKNOWN"
    write_result OS_VERSION "UNKNOWN"
  fi
}
y2b_step_2() {            # check-kernel-version
  # Query active kernel release
  KERNEL_VER=$(uname -r 2>/dev/null || echo "UNKNOWN")
  write_result KERNEL_VERSION "$KERNEL_VER"
}
y2b_step_3() {            # check-uptime-and-load
  # Query system uptime seconds and 1-minute load average
  UPTIME_SECS=$(awk '{print int($1)}' /proc/uptime 2>/dev/null || echo "0")
  LOAD_1M=$(awk '{print $1}' /proc/loadavg 2>/dev/null || echo "0.00")
  write_result UPTIME_SECS "$UPTIME_SECS"
  write_result LOAD_1M "$LOAD_1M"
}
y2b_step_4() {            # check-disk-usage
  # Query root mount usage percentage
  ROOT_USE=$(df -h / | awk 'NR==2 {print $5}' 2>/dev/null || echo "0%")
  write_result ROOT_DISK_USAGE "$ROOT_USE"
}
